// server component
export async function CheckoutServer() {
  const config = await loadConfig(); // { stripePublicKey, stripeSecretKey, currency }
  const session = await getSession();

  return (
    <PaymentWidget
      config={config}
      onSuccess={() => recordPayment(session.userId)}
      currency={config.currency}
    />
  );
}

'use client';
function PaymentWidget({ config, onSuccess, currency }: Props) {
  return <button onClick={onSuccess}>Pay in {currency}</button>;
}
